using Ranki.Services.Interfaces;
using Microsoft.EntityFrameworkCore;
using Ranki.Data;
using Ranki.DTOs;
using Ranki.Exceptions;
using Ranki.Models;
namespace Ranki.Services.Implementations { public class BusinessProfileService : IBusinessProfileService { private readonly AppDbContext _context; public BusinessProfileService(AppDbContext context) { _context = context; } public async Task<BusinessProfile> CreateProfileAsync(int userId, BusinessProfileDto dto) { if (await _context.BusinessProfiles.AnyAsync(b => b.UserId == userId)) return await UpdateProfileAsync(userId, dto); var profile = new BusinessProfile { UserId = userId, BusinessName = dto.BusinessName, WebsiteUrl = dto.WebsiteUrl, Industry = dto.Industry, Country = dto.Country, ProductsServices = dto.ProductsServices, TargetCustomer = dto.TargetCustomer }; _context.BusinessProfiles.Add(profile); await _context.SaveChangesAsync(); return profile; } public async Task<BusinessProfile> GetProfileAsync(int userId) { var profile = await _context.BusinessProfiles.FirstOrDefaultAsync(b => b.UserId == userId); if (profile == null) throw new NotFoundException("Business profile not found."); return profile; } public async Task<BusinessProfile> UpdateProfileAsync(int userId, BusinessProfileDto dto) { var profile = await _context.BusinessProfiles.FirstOrDefaultAsync(b => b.UserId == userId); if (profile == null) throw new NotFoundException("Business profile not found. Use POST to create."); profile.BusinessName = dto.BusinessName; profile.WebsiteUrl = dto.WebsiteUrl; profile.Industry = dto.Industry; profile.Country = dto.Country; profile.ProductsServices = dto.ProductsServices; profile.TargetCustomer = dto.TargetCustomer; profile.UpdatedAt = DateTime.UtcNow; _context.BusinessProfiles.Update(profile); await _context.SaveChangesAsync(); return profile; } } }
